let context;
let enabled=true;
try{enabled=localStorage.getItem('misi-sound')!=='off';}catch{}
export function soundEnabled(){return enabled;}
export function setSound(value){enabled=!!value;try{localStorage.setItem('misi-sound',enabled?'on':'off');}catch{}if(!enabled&&context?.state==='running')context.suspend().catch(()=>{});}
export const NOTES={correct:[[523.25,0,.12],[659.25,.12,.12],[783.99,.24,.2]],wrong:[[329.63,0,.16],[261.63,.18,.22]],finish:[[523.25,0,.12],[659.25,.14,.12],[783.99,.28,.12],[1046.5,.44,.35]],tap:[[659.25,0,.08]]};
export async function playSound(kind){if(!enabled)return false;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return false;context??=new Audio();if(context.state!=='running')await context.resume();if(!enabled)return false;for(const [hz,delay,duration] of NOTES[kind]||NOTES.tap){const oscillator=context.createOscillator(),gain=context.createGain(),start=context.currentTime+delay;oscillator.type='sine';oscillator.frequency.setValueAtTime(hz,start);gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.12,start+.015);gain.gain.exponentialRampToValueAtTime(.001,start+duration);oscillator.connect(gain);gain.connect(context.destination);oscillator.start(start);oscillator.stop(start+duration+.02);oscillator.onended=()=>{oscillator.disconnect();gain.disconnect();};}return true;}catch{return false;}}
export function celebrate(host){if(!host||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const layer=document.createElement('div');layer.className='confetti';layer.setAttribute('aria-hidden','true');for(let i=0;i<18;i++){const piece=document.createElement('span');piece.textContent=['★','✦','●'][i%3];piece.style.setProperty('--x',(i*5.7)+'%');piece.style.setProperty('--delay',(i%6)*.055+'s');piece.style.setProperty('--color',['#eeae2e','#49a080','#9381d5','#ef8f92'][i%4]);layer.append(piece);}host.append(layer);setTimeout(()=>layer.remove(),1600);}
